72	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
73	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
74	  const { isAdmin, loading } = useAuth();
75	
76	  // Don't block rendering while loading — only gate when we know maintenance is on
77	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
78	  return <>{children}</>;
79	};
80	
81	const RootRoute = () => {
82	  const { user, loading } = useAuth();
83	  if (loading) return <PageLoader />;
84	  return user ? <Index /> : <LandingPage />;
85	};
