104	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
105	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
106	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
107	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
108	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
109	                      <Route path="/book-demo" element={<BookDemo />} />
110	                      <Route path="/request-feature" element={<RequestFeature />} />
111	                      <Route path="/changelog" element={<Changelog />} />
112	                      <Route path="/payment/callback" element={<PaymentCallback />} />
113	                      <Route path="*" element={<NotFound />} />
114	                    </Routes>
115	                  </MaintenanceGate>
