117	              </Routes>
118	            </Suspense>
119	            <ChatWidget />
120	          </BrowserRouter>
121	        </TooltipProvider>
122	      </AuthProvider>
123	    </ThemeProvider>
124	  </QueryClientProvider>
125	);
126	
127	export default App;
