20	const MAX_FILE_BYTES = 10 * 1024 * 1024; // 10 MB
21	const ALLOWED_EXTENSIONS = [".pdf", ".docx", ".doc", ".rtf", ".txt"];
22	const ALLOWED_MIME = [
23	  "application/pdf",
24	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
25	  "application/msword",
26	  "text/plain",
27	  "application/rtf",
28	  "text/rtf",
29	];
30	
31	function hasAllowedExtension(filename: string): boolean {
32	  const lower = filename.toLowerCase();
33	  return ALLOWED_EXTENSIONS.some((ext) => lower.endsWith(ext));
34	}
35	
36	interface JobInfo {
37	  id: string;
38	  title: string;
39	  status: string;
40	}
41	
42	export default function Apply() {
43	  const { jobId } = useParams<{ jobId: string }>();
44	  const fileInputRef = useRef<HTMLInputElement>(null);
45	
46	  const [name, setName] = useState("");
47	  const [email, setEmail] = useState("");
48	  const [phone, setPhone] = useState("");
49	  const [linkedinUrl, setLinkedinUrl] = useState("");
50	  const [resumeFile, setResumeFile] = useState<File | null>(null);
51	  const [dragOver, setDragOver] = useState(false);
52	  const [submitting, setSubmitting] = useState(false);
53	  const [submitted, setSubmitted] = useState(false);
54	  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
55	
56	  // Fetch minimal job info — no auth required via RPC
57	  const {
58	    data: job,
59	    isLoading: jobLoading,
60	    error: jobError,
61	  } = useQuery<JobInfo | null>({
62	    queryKey: ["apply-job-info", jobId],
63	    queryFn: async () => {
64	      if (!jobId) return null;
65	      const { data, error } = await supabase.rpc("get_job_apply_info", {
66	        p_job_id: jobId,
67	      });
68	      if (error) throw new Error(error.message);
69	      if (!data || (Array.isArray(data) && data.length === 0)) return null;
70	      const row = Array.isArray(data) ? data[0] : data;
71	      return row as JobInfo;
72	    },
73	    enabled: !!jobId,
74	    retry: 1,
75	    staleTime: 60_000,
76	  });
77	
78	  const handleFileSelect = (file: File) => {
79	    if (file.size > MAX_FILE_BYTES) {
80	      toast.error("File exceeds 10MB limit");
81	      return;
82	    }
83	    if (!ALLOWED_MIME.includes(file.type) && !hasAllowedExtension(file.name)) {
84	      toast.error("Please upload a PDF, DOCX, DOC, RTF, or TXT file");
85	      return;
86	    }
87	    setResumeFile(file);
88	    setFieldErrors((prev) => ({ ...prev, resume: "" }));
89	  };
90	
91	  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
92	    e.preventDefault();
93	    setDragOver(false);
94	    const file = e.dataTransfer.files[0];
95	    if (file) handleFileSelect(file);
96	  };
97	
98	  const validate = (): boolean => {
99	    const errors: Record<string, string> = {};
100	    if (!name.trim()) errors.name = "Name is required";
101	    if (!email.trim()) errors.email = "Email is required";
102	    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))
103	      errors.email = "Enter a valid email address";
104	    setFieldErrors(errors);
105	    return Object.keys(errors).length === 0;
106	  };
107	
108	  const handleSubmit = async (e: React.FormEvent) => {
109	    e.preventDefault();
110	    if (!validate()) return;
111	    if (!jobId) {
112	      toast.error("Invalid application link");
113	      return;
114	    }
115	
116	    setSubmitting(true);
117	    try {
118	      const form = new FormData();
119	      form.append("job_id", jobId);
120	      form.append("name", name.trim());
121	      form.append("email", email.trim().toLowerCase());
122	      if (phone.trim()) form.append("phone", phone.trim());
123	      if (linkedinUrl.trim()) form.append("linkedin_url", linkedinUrl.trim());
124	      if (resumeFile) form.append("resume", resumeFile);
125	
126	      const { data: sessionData } = await supabase.auth.getSession();
127	      const headers: Record<string, string> = {
128	        // Supabase project URL and anon key from env — required even for anon calls
129	        apikey: import.meta.env.VITE_SUPABASE_ANON_KEY as string,
130	      };
131	      if (sessionData.session?.access_token) {
132	        headers["Authorization"] = `Bearer ${sessionData.session.access_token}`;
133	      } else {
134	        headers["Authorization"] = `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY as string}`;
135	      }
136	
137	      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
138	      const res = await fetch(
139	        `${supabaseUrl}/functions/v1/submit-application`,
140	        {
141	          method: "POST",
142	          headers,
143	          body: form,
144	        }
145	      );
146	
147	      const json = await res.json();
148	      if (!res.ok) {
149	        throw new Error(json.error || "Failed to submit application");
150	      }
151	
152	      setSubmitted(true);
